-- Inventario de Verdemagenta: tabla `producto` y sus registros.
-- Lo carga `npm start` (server/preparar-bd.mjs) cuando la tabla no existe o está vacía.
-- A mano: mysql -u root -p inventario_vm < server/bd/inventario_vm.sql

CREATE TABLE IF NOT EXISTS producto (
  id          INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
  producto    VARCHAR(255) NOT NULL,
  precio      DECIMAL(10,2) NOT NULL DEFAULT 0,
  descripcion TEXT NULL,
  categoria   VARCHAR(100) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

